use std::{io as std_io, sync::Arc, time::Duration};

use anyhow::{Context, Result, bail, ensure};
use iroh::EndpointId;
use tokio::{
    io::{self, AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt},
    task::JoinSet,
    time::{sleep, timeout},
};

use crate::{
    invite::Code,
    tunnel::{ClientNotAllowed, SharedTunnel},
};

const READY: u8 = 1;
const FAILED: u8 = 0;
const DENIED: u8 = 2;
// Endpoint IDs generated by iroh cannot be this reserved request prefix.
const INVITATION: [u8; 32] = [0; 32];
pub const IDLE_TIMEOUT: Duration = Duration::from_secs(1);
pub const START_TIMEOUT: Duration = Duration::from_secs(5);

pub fn was_closed(error: &anyhow::Error) -> bool {
    error.downcast_ref::<std_io::Error>().is_some_and(|error| {
        matches!(
            error.kind(),
            std_io::ErrorKind::ConnectionReset
                | std_io::ErrorKind::BrokenPipe
                | std_io::ErrorKind::UnexpectedEof
                | std_io::ErrorKind::ConnectionAborted
        )
    })
}

pub async fn request(
    local: &mut (impl AsyncRead + AsyncWrite + Unpin),
    client: EndpointId,
    peer: EndpointId,
) -> Result<()> {
    local
        .write_all(peer.as_bytes())
        .await
        .context("request local sshi tunnel")?;
    response(local, peer, Some(client)).await
}

pub async fn redeem(
    local: &mut (impl AsyncRead + AsyncWrite + Unpin),
    peer: EndpointId,
    code: &Code,
) -> Result<()> {
    local.write_all(&INVITATION).await?;
    local.write_all(peer.as_bytes()).await?;
    local.write_all(code.as_bytes()).await?;
    response(local, peer, None).await
}

async fn response(
    local: &mut (impl AsyncRead + AsyncWrite + Unpin),
    peer: EndpointId,
    client: Option<EndpointId>,
) -> Result<()> {
    let status = timeout(Duration::from_secs(50), local.read_u8())
        .await
        .context("timed out opening tunnel through the local sshi service")??;
    match (status, client) {
        (READY, _) => Ok(()),
        (DENIED, Some(client)) => Err(ClientNotAllowed { client }.into()),
        _ => {
            let mut reason = String::new();
            timeout(START_TIMEOUT, local.take(4096).read_to_string(&mut reason)).await??;
            bail!("local sshi service could not connect to {peer}: {reason}")
        }
    }
}

enum Request {
    Ssh(EndpointId),
    Invite(EndpointId, Code),
}

pub async fn listen<S>(
    accept: impl AsyncFn() -> std_io::Result<S>,
    tunnel: Arc<SharedTunnel>,
    token: Option<[u8; 32]>,
    idle: Option<Duration>,
) -> Result<()>
where
    S: AsyncRead + AsyncWrite + Unpin + Send + 'static,
{
    let mut sessions = JoinSet::new();
    loop {
        tokio::select! {
            biased;
            local = accept() => {
                let local = local.context("accept local sshi client")?;
                let tunnel = tunnel.clone();
                sessions.spawn(async move {
                    if let Err(error) = forward(local, &tunnel, token).await {
                        eprintln!("local sshi client: {error:#}");
                    }
                });
            }
            _ = sessions.join_next(), if !sessions.is_empty() => {}
            _ = sleep(idle.unwrap_or_default()), if idle.is_some() && sessions.is_empty() => {
                return Ok(());
            }
        }
    }
}

async fn forward(
    mut local: impl AsyncRead + AsyncWrite + Unpin,
    tunnel: &SharedTunnel,
    token: Option<[u8; 32]>,
) -> Result<()> {
    let request = timeout(START_TIMEOUT, async {
        if let Some(expected) = token {
            let mut actual = [0; 32];
            local.read_exact(&mut actual).await?;
            ensure!(actual == expected, "invalid local sshi session token");
        }
        let mut id = [0; 32];
        local.read_exact(&mut id).await?;
        let invitation = id == INVITATION;
        if invitation {
            local.read_exact(&mut id).await?;
        }
        let peer = EndpointId::from_bytes(&id).context("invalid Endpoint ID")?;
        if invitation {
            let mut code = [0; 32];
            local.read_exact(&mut code).await?;
            Ok::<_, anyhow::Error>(Request::Invite(peer, Code::from_bytes(code)))
        } else {
            Ok(Request::Ssh(peer))
        }
    })
    .await
    .context("timed out reading the local tunnel request")??;
    let peer = match request {
        Request::Ssh(peer) => peer,
        Request::Invite(peer, code) => {
            match tunnel.redeem(peer, code).await {
                Ok(()) => local.write_u8(READY).await?,
                Err(error) => return reject(&mut local, error).await,
            }
            local.shutdown().await?;
            return Ok(());
        }
    };
    let opened = tokio::select! {
        result = tunnel.open(peer) => result,
        input = local.read_u8() => {
            if input.is_err_and(|error| error.kind() == std_io::ErrorKind::UnexpectedEof) {
                return Ok(());
            }
            bail!("local client closed or sent SSH bytes before the tunnel was ready");
        }
    };
    let (_connection, send, recv) = match opened {
        Ok(tunnel) => tunnel,
        Err(error) => return reject(&mut local, error).await,
    };
    local.write_u8(READY).await?;
    io::copy_bidirectional(&mut local, &mut io::join(recv, send))
        .await
        .context("forward local SSH stream")?;
    Ok(())
}

async fn reject(local: &mut (impl AsyncWrite + Unpin), error: anyhow::Error) -> Result<()> {
    let status = if error.is::<ClientNotAllowed>() {
        DENIED
    } else {
        FAILED
    };
    local.write_u8(status).await?;
    local.write_all(format!("{error:#}").as_bytes()).await?;
    local.shutdown().await?;
    Ok(())
}
